 using System.ComponentModel;
 using ModelContextProtocol.Server;

 var builder = WebApplication.CreateBuilder(args);

 builder.Services
     .AddMcpServer()
     .WithHttpTransport()
     .WithTools<WeatherTools>()
     .WithResources<ConfigResources>();

 var app = builder.Build();

 app.MapMcp();

 app.Run();

 // --- Tools ---

 [McpServerToolType]
 public static class WeatherTools
 {
     [McpServerTool(Name = "get_weather")]
     [Description("Gets current weather for a city.")]
     public static string GetWeather(string city) =>
         $$"""{"city":"{{city}}","tempC":22,"condition":"Sunny"}""";
 }

 // --- Resources ---

 [McpServerResourceType]
 public static class ConfigResources
 {
     [McpServerResource(UriTemplate = "config://app/settings", Name = "app_settings",
         Description = "Returns application configuration data.")]
     public static string GetAppSettings() =>
         """
         {
           "version": "1.0.0",
           "environment": "production",
           "features": { "darkMode": true, "betaAccess": false },
           "maxConnections": 100
         }
         """;

     [McpServerResource(UriTemplate = "config://app/features/{featureName}", Name = "feature_flag",
         Description = "Returns a specific feature flag value.")]
     public static string GetFeatureFlag(string featureName) =>
         featureName.ToLowerInvariant() switch
         {
             "darkmode" => """{"feature":"darkMode","enabled":true}""",
             "betaaccess" => """{"feature":"betaAccess","enabled":false}""",
             _ => $$"""{"feature":"{{featureName}}","enabled":false,"note":"unknown flag"}"""
         };
 }

